			String methodName;
			if (methodCall.meth instanceof JCIdent) {
				receiver = maker.Ident(annotationNode.toName("this"));
				methodName = ((JCIdent) methodCall.meth).name.toString();
			} else {
				receiver = ((JCFieldAccess) methodCall.meth).selected;
				methodName = ((JCFieldAccess) methodCall.meth).name.toString();
			}
			if ("this".equals(receiver.toString()) || "this".equals(methodName) || "super".equals(methodName)) continue;
			boolean validMethodName = methodName != null && !methodName.isEmpty();
			if (validMethodName) {
				char firstChar = methodName.charAt(0);
				validMethodName = Character.isJavaIdentifierStart(firstChar);
				int nameLength = methodName.length();
				int nameIndex = 1;
				while (validMethodName && nameIndex < nameLength) {
					char currentChar = methodName.charAt(nameIndex);
					validMethodName = Character.isJavaIdentifierPart(currentChar);
					nameIndex++;
				}
